sys_script_fix.script:
(function executeFixScript() {

    gs.log("=== DELETE 'Show Cisco CSA fields' UI POLICIES SCRIPT START ===");

    // Delete all UI Policies with short_description = "Show Cisco CSA fields"
    var policiesToDelete = new GlideRecord('sys_ui_policy');
    policiesToDelete.addQuery('table', 'change_request');
    policiesToDelete.addQuery('short_description', 'Show Cisco CSA fields');
    policiesToDelete.query();

    var deletedCount = 0;
    var deletedPolicyIds = [];

    while (policiesToDelete.next()) {
        var policyId = policiesToDelete.sys_id.toString();
        var policyName = policiesToDelete.short_description.toString();
        var updatedOn = policiesToDelete.sys_updated_on.toString();

        // First delete all UI Policy Actions for this policy
        var actions = new GlideRecord('sys_ui_policy_action');
        actions.addQuery('ui_policy', policyId);
        actions.query();

        var actionCount = 0;
        while (actions.next()) {
            var fieldName = actions.field.toString();
            actions.deleteRecord();
            actionCount++;
            gs.log("  Deleted UI Policy Action for field: " + fieldName);
        }

        // Then delete the UI Policy itself
        policiesToDelete.deleteRecord();
        deletedCount++;
        deletedPolicyIds.push(policyId);

        gs.log("Deleted UI Policy: '" + policyName + "' (ID: " + policyId + ", Updated: " + updatedOn + ") - Removed " + actionCount + " actions");
    }

    // Verification - check if any remain
    gs.log("--- Verification ---");
    var remainingPolicies = new GlideRecord('sys_ui_policy');
    remainingPolicies.addQuery('table', 'change_request');
    remainingPolicies.addQuery('short_description', 'Show Cisco CSA fields');
    remainingPolicies.query();

    if (remainingPolicies.hasNext()) {
        gs.log("⚠️ WARNING: Some 'Show Cisco CSA fields' policies still exist!");
        while (remainingPolicies.next()) {
            gs.log("  Remaining: " + remainingPolicies.short_description + " (ID: " + remainingPolicies.sys_id + ")");
        }
    } else {
        gs.log("✅ SUCCESS: All 'Show Cisco CSA fields' UI Policies have been deleted");
    }

    gs.log("=== DELETION COMPLETED ===");
    gs.log("Total UI Policies deleted: " + deletedCount);
    gs.log("Deleted Policy IDs: " + deletedPolicyIds.join(", "));
    gs.log("✅ Ready to run your UI Policy creation fix script");

})();
